using namespace std;

class Solution {
public:
    long long minimumTime(vector<int>& deliveries, vector<int>& workers) {
        long long target = 0;
        for (int d : deliveries) target += d;
        long long min_w = *min_element(workers.begin(), workers.end());
        long long low = 1, high = target * min_w;
        long long ans = high;
        while (low <= high) {
            long long mid = low + (high - low) / 2;
            long long total = 0;
            for (int w : workers) {
                total += mid / w;
            }
            if (total >= target) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public long minimumTime(int[] deliveries, int[] workers) {
        long target = 0;
        for (int d : deliveries) target += d;
        long minW = workers[0];
        for (int w : workers) minW = Math.min(minW, w);
        long low = 1, high = target * minW;
        long ans = high;
        while (low <= high) {
            long mid = low + (high - low) / 2;
            long total = 0;
            for (int w : workers) {
                total += mid / w;
            }
            if (total >= target) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}

var minimumTime = function(deliveries, workers) {
    let target = 0n;
    for (const d of deliveries) target += BigInt(d);
    let minW = BigInt(workers[0]);
    for (const w of workers) {
        if (BigInt(w) < minW) minW = BigInt(w);
    }
    let low = 1n, high = target * minW;
    let ans = high;
    while (low <= high) {
        const mid = (low + high) / 2n;
        let total = 0n;
        for (const w of workers) {
            total += mid / BigInt(w);
        }
        if (total >= target) {
            ans = mid;
            high = mid - 1n;
        } else {
            low = mid + 1n;
        }
    }
    return Number(ans);
};
